'use strict'

const bufferFrom = Buffer.from || Buffer

/**
 * Parse a PostgreSQL bytea string into a Buffer.
 *
 * PostgreSQL returns bytea values in one of two formats:
 * - Hex format: a leading backslash and lowercase x followed by hex digits.
 *   Example: "\\xDEADBEEF"
 * - Escape format: ASCII characters with backslash-escaped octal triplets
 *   for non-printable bytes and doubled backslashes for literal backslashes.
 *
 * @param {string} input
 * @returns {Buffer}
 */
module.exports = function parseBytea (input) {
  if (isHexFormat(input)) {
    return decodeHex(input)
  }
  return decodeEscapeFormat(input)
}

/**
 * Determine whether the input uses PostgreSQL's hex bytea format.
 *
 * @param {string} input
 * @returns {boolean}
 */
function isHexFormat (input) {
  return /^\\x/.test(input)
}

/**
 * Decode a hex-format bytea string into a Buffer.
 *
 * @param {string} input
 * @returns {Buffer}
 */
function decodeHex (input) {
  return bufferFrom(input.substr(2), 'hex')
}

/**
 * Decode an escape-format bytea string into a Buffer.
 *
 * @param {string} input
 * @returns {Buffer}
 */
function decodeEscapeFormat (input) {
  let output = ''
  let i = 0
  while (i < input.length) {
    if (input[i] !== '\\') {
      output += input[i]
      ++i
    } else {
      const octalResult = readOctalSequence(input, i)
      if (octalResult) {
        output += octalResult.char
        i = octalResult.nextIndex
      } else {
        const backslashResult = readBackslashes(input, i)
        output += backslashResult.output
        i = backslashResult.nextIndex
      }
    }
  }
  return bufferFrom(output, 'binary')
}

/**
 * Attempt to read a backslash-escaped octal triplet starting at startIndex.
 *
 * The leading backslash is assumed to be at startIndex. If the next three
 * characters are valid octal digits, they are converted to a single
 * character code; otherwise null is returned.
 *
 * @param {string} input
 * @param {number} startIndex
 * @returns {{char: string, nextIndex: number}|null}
 */
function readOctalSequence (input, startIndex) {
  const octalDigits = input.substr(startIndex + 1, 3)
  if (!/^[0-7]{3}$/.test(octalDigits)) {
    return null
  }
  return {
    char: String.fromCharCode(parseInt(octalDigits, 8)),
    nextIndex: startIndex + 4
  }
}

/**
 * Read a run of consecutive backslashes starting at startIndex.
 *
 * PostgreSQL's escape format collapses each pair of backslashes into one
 * literal backslash. This function returns the resulting literal backslashes
 * and the index immediately after the consumed backslashes.
 *
 * @param {string} input
 * @param {number} startIndex
 * @returns {{output: string, nextIndex: number}}
 */
function readBackslashes (input, startIndex) {
  let count = 1
  while (startIndex + count < input.length && input[startIndex + count] === '\\') {
    count++
  }
  const literalCount = Math.floor(count / 2)
  let output = ''
  for (let k = 0; k < literalCount; ++k) {
    output += '\\'
  }
  return {
    output: output,
    nextIndex: startIndex + literalCount * 2
  }
}